import url from './url.js';
import { renderMoney } from './money.js';
import { localeTimeString } from './time.js';


const urls = {
  tariff_view: `${url.BASE_URL}/tariff-view.json`,
};

// Fetching helper
const fetcher = async (url, params) => {
  try {
    const res = await fetch(url, {
      method: "get",
      ...params,
    });
    const parsed = await res.json();
      return parsed;
  } catch ({ message }) {
    return null;
  }
};

const fetchTariffViewData = async () => fetcher(urls.tariff_view, null);

const mapChunk = (chunk, currency) => ({
  ...chunk,
  costPerKwh: renderMoney({ ...(chunk.costPerKwh || { significand: 0, power: 0 }), currency }),
  costPerMinute: chunk.costPerMinute
    ? renderMoney({ ...chunk.costPerMinute, currency })
    : undefined,
  maxCostTime: chunk.maxCostTime
    ? renderMoney({ ...chunk.maxCostTime, currency })
    : undefined,
  time: localeTimeString(
    chunk.time ? chunk.time.start : 0,
    chunk.time ? chunk.time.end : 0,
  ),
});

const mapTariff = (station) => {
  const { tariff, currency } = station;

  if (tariff.version === 'V2') {
    return {
      ...tariff,
      chunks: (tariff.chunks || []).map(c => mapChunk(c, currency)),
    };
  }

  // V1 (and TARIFF_VERSION_UNSPECIFIED fallback)
  const day = tariff.day ? mapChunk(tariff.day, currency) : undefined;
  // NOTE: Don't show tariff when it's maxCostTime is 0
  const night = tariff.night && tariff.night.maxCostTime?.significand ? mapChunk(tariff.night, currency) : undefined;
  return {
    ...tariff,
    day,
    night,
  };
};

export async function getStations() {
  const locationsWithTariffs = await fetchTariffViewData();
  // show error message
  if (!locationsWithTariffs) {
    this.errorMsg = "Something went wrong, please contact Qwello";
    return;
  }
  this.stations = locationsWithTariffs.map((station) => ({
    ...station,
    tariff: mapTariff(station),
  }));
}

