// Money conversion helpers
const convertToPlaceValue = ({ significand, power }) => 10 ** power * significand;

const convertToString = (significand, power, currency) => {
  power = power ?? 0;
  const minFractionDigits = Math.max(2, Math.abs(power));
  return significand.toLocaleString('de-DE', {
    minimumFractionDigits: minFractionDigits,
  }) + currencySigns[currency];
};

export const renderMoney = ({significand, power, currency}) => {
  return convertToString(convertToPlaceValue({ significand, power }), power, currency);
}

