export function localeTimeString(start, end) {
  const startHour = start / 60;
  const endHour = end / 60;

  let time = new Intl.DateTimeFormat('de-DE', {
    hour: 'numeric',
    minute: 'numeric',
  });

  return `${time.format(c_time(startHour))} to ${time.format(c_time(endHour))}`; // time range -> 7:00 to 19:00
}

const c_time = (time) => new Date().setHours(time, 0, 0);

